-- ==============================================================================
-- TAWI SEED DATA — St. Mary's Primary School
-- Run this in: Supabase Dashboard → SQL Editor → New Query → Run
--
-- What this does:
--   1. Upserts St. Mary's school (fixed UUID so safe to re-run)
--   2. Upserts 5 classes (PP1 Yellow, G1 Yellow, G2 Red, G3 Blue, G4 Blue)
--   3. Inserts ~100 learners across those classes
--   4. Inserts events: attendance, assessments, observations, incidents
--
-- RLS NOTE: Run this as the Supabase service-role (SQL Editor uses service role
--           by default), so RLS policies are bypassed for seeding.
-- ==============================================================================

-- ─── 0. DISABLE RLS TEMPORARILY FOR SEED ─────────────────────────────────────
-- (SQL Editor already runs as service-role; this is just a safety flag)
-- set role postgres; (runs as postgres by default)

-- ─── 1. SCHOOL ────────────────────────────────────────────────────────────────
insert into public.schools (id, code, name, status)
values (
  '11111111-1111-1111-1111-111111111111',
  'ST_MARYS_001',
  'St. Mary''s Primary School',
  'live'
)
on conflict (id) do update set name = excluded.name, status = excluded.status;

-- ─── 2. CLASSES ───────────────────────────────────────────────────────────────
