-- ─── 5. DEMO ACCESS (Allow frontend anonymous client to read & record data) ───
-- Required because the frontend currently uses role PINs without Supabase Auth JWTs.
-- This ensures the UI is NOT blank when queried with the Supabase anon key.
grant usage on schema public to anon, authenticated;
grant select on public.schools, public.classes, public.learners, public.events to anon, authenticated;
grant insert, update, delete on public.learners, public.events to anon, authenticated;

drop policy if exists "Demo anon read schools" on public.schools;
create policy "Demo anon read schools" on public.schools for select to anon using (true);

drop policy if exists "Demo anon read classes" on public.classes;
create policy "Demo anon read classes" on public.classes for select to anon using (true);

drop policy if exists "Demo anon read learners" on public.learners;
create policy "Demo anon read learners" on public.learners for select to anon using (true);

drop policy if exists "Demo anon read events" on public.events;
create policy "Demo anon read events" on public.events for select to anon using (true);

drop policy if exists "Demo anon write events" on public.events;
create policy "Demo anon write events" on public.events for insert to anon with check (true);

drop policy if exists "Demo anon write learners" on public.learners;
create policy "Demo anon write learners" on public.learners for insert to anon with check (true);

-- ─── 6. VERIFY ────────────────────────────────────────────────────────────────
select
  c.name as class,
  count(distinct l.id) as learners,
  count(distinct e.id) as events
from public.classes c
left join public.learners l on l.class_id = c.id
left join public.events e on e.class_id = c.id
where c.school_id = '11111111-1111-1111-1111-111111111111'
group by c.name, c.created_at
order by c.created_at;
